package com.newzkl.platform.base.biz.order.model.req;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Data;import lombok.NoArgsConstructor;import java.io.Serializable;/** * 聊天请求 */@Data@Builder@AllArgsConstructor@NoArgsConstructorpublic class ChatRequest implements Serializable {    private static final long serialVersionUID = 1L;    /**     * 用户 ID（可选，未传则生成临时 ID）     */    private String userId;    /**     * 会话 ID（可选，未传则新建会话）     */    private String conversationId;    /**     * 用户输入消息     */    private String message;}